/* ---------------- PDF PARSING ---------------- */
async function readPdf(file){
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({data:buf}).promise;
  let lines = [], fullText = "";
  for(let p=1;p<=pdf.numPages;p++){
    const page = await pdf.getPage(p);
    const tc = await page.getTextContent();
    const frags = tc.items.filter(it=>it.str.trim()).map(it=>({
      x:it.transform[4], y:it.transform[5], s:it.str, h:Math.abs(it.transform[3])||10
    }));
    if(!frags.length) continue;
    frags.sort((a,b)=> b.y-a.y || a.x-b.x);
    const tol = Math.max(4, (frags.reduce((s,f)=>s+f.h,0)/frags.length)*0.6);
    let cur=[], curY=null;
    const flush=()=>{ if(!cur.length) return;
      cur.sort((a,b)=>a.x-b.x);
      const ln = cur.map(o=>o.s).join(" ").replace(/\s+/g," ").trim();
      lines.push(ln); fullText += ln + "\n"; cur=[]; };
    frags.forEach(f=>{
      if(curY===null || Math.abs(f.y-curY)<=tol){ cur.push(f); if(curY===null) curY=f.y; }
      else { flush(); cur.push(f); curY=f.y; }
    });
    flush();
  }
  return {lines, fullText};
}

function parseRomaneio(lines, fullText){
  const tagRe = /\bT\d{6,10}\b/i;
  const found = [];
  lines.forEach(line=>{
    // toda linha de item começa com o nº do item: "1 ...", "24 ..."
    const lm = line.match(/^(\d{1,3})\s+(.+)$/);
    if(!lm) return;
    const num = lm[1];
    const rest = lm[2];
    const hasMaterial = /[A-ZÀ-Ú]{3,}/.test(rest);
    const hasTag = tagRe.test(rest);
    const hasLote = /\b\d{1,3}\.\d{2}\b/.test(rest);
    const hasProd = /EM PRODU/i.test(rest);
    if(!hasMaterial) return;                 // descarta linhas vazias tipo "23"
    if(!(hasTag||hasLote||hasProd)) return;  // precisa parecer item de romaneio

    const tagM = rest.match(tagRe);
    const etiqueta = tagM ? tagM[0].toUpperCase() : "";

    // descrição = texto até a primeira quantidade/lote, sem a etiqueta e sem destino/produção
    let work = rest.replace(tagRe,' ');
    const cut = work.search(/\s\d[\d.]*,\d{2}(?=\s|$)|\s\d{1,3}\.\d{2}(?=\s|$)/);
    let desc = (cut>0 ? work.slice(0,cut) : work);
    desc = desc.replace(/\b(EM PRODU\w+|PETROLANDIA|AGROLANDIA)\b/ig,'').replace(/\s+/g,' ').trim();
    const qtdM = work.match(/(?:^|\s)(\d[\d.]*,\d{2})(?=\s|$)/);   // Qtd. Produto = 1o decimal grande
    const qtd = qtdM ? qtdM[1] : '';

    const loteMatches = [...rest.matchAll(/\b\d{1,3}\.\d{2}\b/g)];
    let lote = "", destino = "";
    if(loteMatches.length){
      const last = loteMatches[loteMatches.length-1];
      lote = last[0];
      let after = rest.slice(last.index + last[0].length);          // destino vem logo apos o lote
      after = after.replace(/EM\s+PRODU[A-Za-zÀ-ÿ]*/ig,' ');        // remove "EM PRODUÇÃO" (com acento)
      after = after.replace(/\bOK\b/ig,' ').replace(/[^A-Za-zÀ-ÿ\s]/g,' ');
      destino = after.replace(/\s+/g,' ').trim().toUpperCase();
    }

    found.push({num, etiqueta, descricao:desc, lote, destino, qtd, qtdNum:parseNum(qtd), feito:0, tags:[],
      status: etiqueta?'pendente':'aguardando', manualTag:false, isNew:false});
  });
  // dedup por nº do item
  const seen=new Set(); const unique=[];
  found.forEach(f=>{ if(!seen.has(f.num)){ seen.add(f.num); unique.push(f); }});
  unique.sort((a,b)=>(+a.num)-(+b.num));

  const loteCount={}; unique.forEach(u=>{ if(u.lote) loteCount[u.lote]=(loteCount[u.lote]||0)+1; });
  const loteMain = Object.keys(loteCount).sort((a,b)=>loteCount[b]-loteCount[a])[0] || "";
  const destCount={}; unique.forEach(u=>{ if(u.destino) destCount[u.destino]=(destCount[u.destino]||0)+1; });
  const destMain = Object.keys(destCount).sort((a,b)=>destCount[b]-destCount[a])[0] || "";
  const get = re => { const m = fullText.match(re); return m ? m[1].trim() : ""; };
  const resp = get(/Respons[áa]vel\s+Romaneio\s*:\s*([^\n]+?)(?:\s+Data\b|\s+Conferente|\s+Operador|\s+Embarque|\n|$)/i);
  const dataRom = get(/Data\s+Romaneio\s*:\s*(\d{1,2}\/\d{1,2}\/\d{2,4})/i);
  const dataEmb = get(/Data\s+de\s+Embarque\s*:\s*(\d{1,2}\/\d{1,2}\/\d{2,4})/i);

  return {items:unique, loteMain, destMain, resp, dataRom, dataEmb};
}

/* ---------------- RENDER ---------------- */
function renderHeader(meta){
  document.getElementById('loteNum').textContent = meta.loteMain || '—';
  const dEl = document.getElementById('loteDest'); if(dEl) dEl.textContent = meta.destMain || '';
  const waiting = items.filter(i=>!i.etiqueta && !itemSep(i)).length;
  const chips = [];
  chips.push(`<span class="chip">Itens <b>${items.length}</b></span>`);
  if(waiting) chips.push(`<span class="chip wait">A separar <b>${waiting}</b></span>`);
  if(meta.resp) chips.push(`<span class="chip">Resp. <b>${meta.resp}</b></span>`);
  if(meta.dataRom) chips.push(`<span class="chip">Romaneio <b>${meta.dataRom}</b></span>`);
  if(meta.dataEmb) chips.push(`<span class="chip">Embarque <b>${meta.dataEmb}</b></span>`);
  document.getElementById('loteMeta').innerHTML = chips.join('');
  document.getElementById('prodNote').textContent = waiting ? `${waiting} a separar` : '';
}

function renderItems(){
  const el = document.getElementById('itemList');
  el.innerHTML = items.map(it=>{
    const admBar = `<div class="adm-actions">${it.etiqueta?`<button class="adm-b" type="button" onclick="EXP.admEditTag('${it.num}')">Editar etiqueta</button>`:`<button class="adm-b" type="button" onclick="EXP.toggleManual('${it.num}')">Etiqueta manual</button>`}<button class="adm-b" type="button" onclick="EXP.admEditQty('${it.num}')">Qtd. Produto</button><button class="adm-b" type="button" onclick="EXP.admResetItem('${it.num}')">↶ Voltar processo</button><button class="adm-b del" type="button" onclick="EXP.admDelItem('${it.num}')">Excluir item</button></div>`;
    if(!it.etiqueta){
      const meta=it.qtdNum||0, feito=it.feito||0;
      const pct=meta?Math.min(100,Math.round(feito/meta*100)):0;
      const sep=meta>0 && feito>=meta-0.001;
      const tagsArr=it.tags||[];
      const confCount=tagsArr.filter(t=>t.conf).length;
      const confAll= it.forceDone || (sep && tagsArr.length>0 && confCount===tagsArr.length);
      const cls=confAll?'conferido':(sep?'separado':(feito>0?'parcial':'aguardando'));
      const loteChip = it.lote ? `<span class="lotechip">Lote ${it.lote}</span>` : '';
      const metaChip = meta ? `<span class="qtdchip">Qtd. Produto ${it.qtd||fmtNum(meta)}</span>` : '';
      const statusChip = confAll ? '<span class="manual done-chip">Conferido</span>'
        : (sep ? `<span class="manual sep-chip">Conferir ${confCount}/${tagsArr.length}</span>` : '');
      const tagsHtml=tagsArr.map((t,ix)=>`<div class="qtag ${t.conf?'ok':''}"><span class="qt-t">${t.tag}</span><span class="qt-q">${fmtNum(t.q)}</span>${t.conf?'<span class="qt-ck">✓</span>':`<button class="qt-x" type="button" onclick="EXP.removeQtyTag('${it.num}',${ix})" aria-label="Remover">✕</button>`}</div>`).join('');
      const prog = meta ? `<div class="qprog"><div class="qbar ${sep?'full':''}"><i style="width:${pct}%"></i></div><div class="qlabel">Feito <b>${fmtNum(feito)}</b> / ${it.qtd||fmtNum(meta)} <span>(${pct}%)</span></div></div>` : '';
      const scanTxt = sep ? ((mode==='conf' && !confAll) ? 'Conferir etiquetas' : 'Escanear mais') : 'Escanear etiqueta';
      return `<div class="item ${cls}">
        <div class="stat">${confAll?'✓':(sep?'●':(feito>0?'◐':'⧖'))}</div>
        <div class="body">
          <div class="tag dim">#${it.num} · ${loteChip}${metaChip}${statusChip}</div>
          <div class="desc">${it.descricao||'—'}</div>
          ${prog}
          ${tagsHtml?`<div class="qtags">${tagsHtml}</div>`:''}
          <button type="button" class="scanitem ${sep?'more':''}" onclick="EXP.openCam('${it.num}')">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3.4"/></svg>
            ${scanTxt}
          </button>
          ${admBar}
          ${sep?'':`<div class="addtag manual-fields hidden" id="mf_${it.num}">
            <input class="ti" id="ti_${it.num}" placeholder="Etiqueta (T...)" autocomplete="off" autocapitalize="characters">
            <input class="tq" id="tq_${it.num}" placeholder="Qtd" inputmode="decimal" autocomplete="off" onkeydown="if(event.key==='Enter')addQtyTag('${it.num}')">
            <button class="qadd" type="button" onclick="EXP.addQtyTag('${it.num}')" aria-label="Adicionar">＋</button>
          </div>`}
        </div>
      </div>`;
    }
    const icon = it.status==='conferido'?'✓':(it.status==='separado'?'●':'○');
    const badge = it.status==='conferido'?'Conferido':(it.status==='separado'?'Separado':'Pendente');
    const tagMark = it.isNew?'<span class="nova">Nova</span>':(it.manualTag?'<span class="manual">Manual</span>':'');
    const loteChip = it.lote ? `<span class="lotechip">Lote ${it.lote}</span>` : '';
    const qtdChip = it.qtd ? `<span class="qtdchip">Qtd ${it.qtd}</span>` : '';
    const isT = (it.etiqueta||'').toUpperCase().startsWith('T');
    const saldoBlock = (it.status==='conferido' && isT) ? `<div class="saldo-wrap">${it.saldo?`<div class="saldo-chip">Saldo a mais: <b>${fmtNum(it.saldo)}</b><button type="button" class="saldo-del" onclick="EXP.setSaldo('${it.num}',0)" aria-label="Remover saldo">✕</button></div>`:''}<div class="saldo-add"><input class="saldo-in" id="sld_${it.num}" placeholder="Qtd a mais" inputmode="decimal" autocomplete="off" onkeydown="if(event.key==='Enter'){event.preventDefault();addSaldo('${it.num}')}"><button class="saldo-b" type="button" onclick="EXP.addSaldo('${it.num}')">Acrescentar saldo</button></div></div>` : '';
    const camBtn = it.status!=='conferido'
      ? `<button class="icam" type="button" onclick="EXP.openCam()" aria-label="Escanear etiqueta">
           <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 4h-5L7 7H4a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-3l-2.5-3z"/><circle cx="12" cy="13" r="3.2"/></svg>
         </button>`
      : `<div class="badge">${badge}</div>`;
    var _noChao=false;try{_noChao=(it.status!=='conferido' && it.etiqueta && typeof window.wmsChaoTemEtiqueta==='function' && window.wmsChaoTemEtiqueta(it.etiqueta));}catch(e){}
    var _chaoChip=_noChao?'<span class="chao-chip">no chão ✓</span>':'';
    return `<div class="item ${it.status}${_noChao?' emchao':''}">
      <div class="stat">${icon}</div>
      <div class="body">
        <div class="tag">${it.etiqueta}${loteChip}${tagMark}${_chaoChip}</div>
        <div class="desc">#${it.num} · ${it.descricao||'—'}</div>
        ${it.qtd?`<div class="qty-line">Qtd. Produto <b>${it.qtd}</b></div>`:''}
        ${saldoBlock}
        ${(it.status!=='conferido' && adminMode)?`<div class="op-actions">
          <button class="op-b" type="button" onclick="EXP.markStatus('${it.num}','separado')">✓ Separado</button>
          <button class="op-b ok" type="button" onclick="EXP.markStatus('${it.num}','conferido')">✓✓ Pronto</button>
        </div>`:''}
        ${admBar}
      </div>
      ${camBtn}
    </div>`;
  }).join('');
}

function addManualTag(num){
  const inp = document.getElementById('ti_'+num);
  if(!inp) return;
  const v = inp.value.trim();
  if(!v) return;
  if(items.some(i=>i.etiqueta && norm(i.etiqueta)===norm(v))){
    beep('err'); banner('err','⛔','Etiqueta repetida','Esse código já está em outro item do romaneio'); return;
  }
  const it = items.find(i=>i.num===num);
  it.etiqueta = v.toUpperCase(); it.status='pendente'; it.manualTag=true;
  auditEvent('etiqueta_manual','Item #'+num+' · '+it.etiqueta+'.');
  beep('sep'); vibrate('sep');
  banner('sep','🏷️','Etiqueta adicionada',`<span class="mono">${it.etiqueta}</span> · ${it.descricao||''}`);
  renderItems(); updateProgress();
}
function recalcItem(it){
  it.feito=(it.tags||[]).reduce((s,t)=>s+(t.q||0),0);
  if(it.forceDone){ it.status='separado'; return; }
  if(it.qtdNum>0 && it.feito>=it.qtdNum-0.001) it.status='separado';
  else if(it.feito>0) it.status='parcial';
  else it.status='aguardando';
}
function markStatus(num, st){
  if(!expAdminAllowed(true)) return;
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  if(it.etiqueta){ it.status=st; }
  else { it.forceDone=true; recalcItem(it); }
  /* ao CONFERIR (saída), dá baixa da etiqueta no Chão de expedição do WMS, se estiver lá */
  var _baixou=false;
  if(st==='conferido' && it.etiqueta){
    try{ if(typeof window.wmsChaoBaixaEtiqueta==='function' && window.wmsChaoTemEtiqueta && window.wmsChaoTemEtiqueta(it.etiqueta)){ _baixou=window.wmsChaoBaixaEtiqueta(it.etiqueta); } }catch(e){}
  }
  auditEvent('status_manual','Item #'+num+' alterado manualmente para '+st+'.');
  syncActive(); renderItems(); updateProgress();
  beep(st==='conferido'?'conf':'sep'); vibrate('sep');
  banner('ok','✓', st==='conferido'?'Marcado como pronto':'Marcado como separado', '#'+num+(it.etiqueta?` · ${it.etiqueta}`:'')+(_baixou?' · baixado do chão':''));
}
function toggleManual(num){
  if(!expAdminAllowed(true)) return;
  const mf=document.getElementById('mf_'+num); if(!mf) return;
  mf.classList.toggle('hidden');
  const f=mf.querySelector('input'); if(f && !mf.classList.contains('hidden')) setTimeout(()=>{try{f.focus();}catch(e){}},50);
}
function addSaldo(num){
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  const el=document.getElementById('sld_'+num); if(!el) return;
  const v=parseNum(el.value);
  if(v<=0){ beep('err'); banner('warn','✏️','Falta a quantidade','Digite a quantidade que sobrou'); el.focus(); return; }
  it.saldo=(it.saldo||0)+v; el.value='';
  auditEvent('saldo_acrescentado','Item #'+num+' · '+(it.etiqueta||'Sem etiqueta')+' · +'+v+' · total '+it.saldo+'.');
  syncActive(); renderItems(); updateProgress();
  beep('sep'); vibrate('sep');
  banner('ok','','Saldo acrescentado',`<span class="mono">${it.etiqueta}</span> · +${fmtNum(v)} (total ${fmtNum(it.saldo)})`);
}
function setSaldo(num,val){
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  it.saldo=val||0; if(!it.saldo) delete it.saldo;
  auditEvent('saldo_alterado','Item #'+num+' · '+(it.etiqueta||'Sem etiqueta')+' · saldo definido como '+(val||0)+'.');
  syncActive(); renderItems(); updateProgress();
}
function addQtyTag(num){
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  const tagInp=document.getElementById('ti_'+num), qInp=document.getElementById('tq_'+num);
  if(!tagInp||!qInp) return;
  let tag=(tagInp.value||'').trim().toUpperCase();
  const m=tag.match(/T\s*\d{4,12}/i); if(m) tag=m[0].replace(/\s+/g,'');
  const q=parseNum(qInp.value);
  if(!/^T\d{4,12}$/i.test(tag)){ beep('err'); vibrate('err'); banner('err','⛔','Etiqueta inválida','A etiqueta começa com T (ex: T40364663)'); tagInp.focus(); return; }
  if(q<=0){ beep('err'); banner('warn','✏️','Falta a quantidade','Digite a quantidade desta etiqueta'); qInp.focus(); return; }
  it.tags=it.tags||[];
  if(it.tags.some(t=>t.tag===tag) || items.some(i=>i.etiqueta && norm(i.etiqueta)===norm(tag))){
    beep('err'); banner('warn','↺','Etiqueta repetida',`<span class="mono">${tag}</span> já foi usada`); return;
  }
  it.tags.push({tag,q}); recalcItem(it);
  auditEvent('etiqueta_adicionada','Item #'+num+' · '+tag+' · quantidade '+q+'.');
  const done=itemSep(it);
  beep(done?'conf':'sep'); vibrate('sep');
  banner(done?'ok':'sep', done?'✅':'➕', done?'Item completo':'Quantidade somada',
    `<span class="mono">${tag}</span> · ${fmtNum(q)} — ${fmtNum(it.feito)}/${fmtNum(it.qtdNum)}`);
  syncActive(); renderItems(); updateProgress();
  const nf=document.getElementById('ti_'+num); if(nf) nf.focus();
}
function removeQtyTag(num,idx){
  if(!expAdminAllowed(true)) return;
  const it=items.find(i=>String(i.num)===String(num)); if(!it||!it.tags) return;
  const antiga=it.tags[idx]; it.tags.splice(idx,1); auditEvent('etiqueta_removida_manual','Item #'+num+' · '+((antiga&&antiga.tag)||'etiqueta')+'.'); recalcItem(it); syncActive(); renderItems(); updateProgress();
}

function updateProgress(){
  const total = items.length;
  const sep = items.filter(itemSep).length;
  const conf = items.filter(itemDone).length;
  const waiting = items.filter(i=>!i.etiqueta && !itemSep(i)).length;
  document.getElementById('cSep').textContent=sep;
  document.getElementById('cConf').textContent=conf;
  ['tTotal','tTotal2','pTot1','pTot2'].forEach(id=>document.getElementById(id).textContent=total);
  document.getElementById('pSep').textContent=sep;
  document.getElementById('pConf').textContent=conf;
  document.getElementById('barSep').style.width = total?(sep/total*100)+'%':'0%';
  document.getElementById('barConf').style.width = total?(conf/total*100)+'%':'0%';
  // anel de progresso (conferido)
  const ring = document.getElementById('ringFg');
  if(ring){
    const C = 2*Math.PI*52;
    const pct = total ? conf/total : 0;
    ring.style.strokeDasharray = C;
    ring.style.strokeDashoffset = C*(1-pct);
    const pe = document.getElementById('ringPct'); if(pe) pe.textContent = Math.round(pct*100)+'%';
  }
  document.getElementById('doneCard').classList.toggle('hidden', !(total>0 && conf===total && waiting===0));
  updateCamCount();
  try{ syncActive(); renderLotes(); }catch(e){}
}

/* ---------------- FEEDBACK ---------------- */
function beep(type){
  try{
    audioCtx = audioCtx || new (window.AudioContext||window.webkitAudioContext)();
    const o=audioCtx.createOscillator(), g=audioCtx.createGain();
    o.connect(g); g.connect(audioCtx.destination); o.type='square';
    o.frequency.value = type==='err'?180 : (type==='conf'?990:740);
    g.gain.value=0.08; o.start();
    setTimeout(()=>o.stop(), type==='err'?320:120);
  }catch(e){}
}
function vibrate(type){ if(navigator.vibrate) navigator.vibrate(type==='err'?[90,60,90]:170); }

let _bnrT=null;
function banner(kind, ic, title, sub){
  const ov=document.getElementById('camOverlay');
  if(ov && !ov.classList.contains('hidden')){
    const cs=document.getElementById('camStatus');
    cs.className='cam-status '+kind;
    cs.innerHTML=`${ic?`<span class="csi">${ic}</span>`:''}<span class="cst"><b>${title}</b><small>${sub}</small></span>`;
    void cs.offsetWidth; cs.classList.add('show');
    clearTimeout(_bnrT); _bnrT=setTimeout(()=>cs.classList.remove('show'), 2400);
    return;
  }
  const b=document.getElementById('banner');
  b.className='banner '+kind;
  const bIcEl=document.getElementById('bIc'); bIcEl.textContent=ic; bIcEl.style.display=ic?'':'none';
  document.getElementById('bTitle').textContent=title;
  document.getElementById('bSub').innerHTML=sub;
  void b.offsetWidth; b.classList.add('show');
  clearTimeout(_bnrT); _bnrT=setTimeout(()=>b.classList.remove('show'), 2800);
}

/* ---------------- FOTOS DA CARGA ---------------- */
let _fdb=null;
function fidb(){
  return new Promise((res,rej)=>{
    if(_fdb) return res(_fdb);
    try{
      const r=indexedDB.open('packem_fotos',1);
      r.onupgradeneeded=()=>{ const db=r.result; if(!db.objectStoreNames.contains('fotos')){ const s=db.createObjectStore('fotos',{keyPath:'id'}); s.createIndex('lote','loteId',{unique:false}); } };
      r.onsuccess=()=>{ _fdb=r.result; res(_fdb); };
      r.onerror=()=>rej(r.error);
    }catch(e){ rej(e); }
  });
}
async function fotoPutRaw(id,loteId,dataUrl,ts){ const db=await fidb(); return new Promise((res)=>{ const tx=db.transaction('fotos','readwrite'); tx.objectStore('fotos').put({id,loteId,dataUrl,ts:ts||Date.now()}); tx.oncomplete=()=>res(); tx.onerror=()=>res(); }); }
async function fotoAdd(loteId,dataUrl){ const id='f'+Date.now()+Math.random().toString(36).slice(2,6); const ts=Date.now(); await fotoPutRaw(id,loteId,dataUrl,ts); supaFotoPush({id,loteId,dataUrl,ts}); return id; }
async function fotoList(loteId){ const db=await fidb(); return new Promise((res)=>{ const out=[]; const idx=db.transaction('fotos').objectStore('fotos').index('lote'); const rq=idx.openCursor(IDBKeyRange.only(loteId)); rq.onsuccess=e=>{ const c=e.target.result; if(c){ out.push(c.value); c.continue(); } else res(out.sort((x,y)=>x.ts-y.ts)); }; rq.onerror=()=>res(out); }); }
async function fotoDel(id){ const db=await fidb(); return new Promise((res)=>{ const tx=db.transaction('fotos','readwrite'); tx.objectStore('fotos').delete(id); tx.oncomplete=()=>res(); tx.onerror=()=>res(); }); }
async function fotoDelLote(loteId){ try{ const list=await fotoList(loteId); const db=await fidb(); const tx=db.transaction('fotos','readwrite'); list.forEach(f=>tx.objectStore('fotos').delete(f.id)); }catch(e){} try{ fetch(SUPA_FOTOS+'?lote_id=eq.'+encodeURIComponent(String(loteId)),{method:'DELETE',headers:supaHeaders()}); }catch(e){} }
async function supaFotoPush(f){ try{ await fetch(SUPA_FOTOS,{method:'POST',headers:supaHeaders({'Prefer':'resolution=merge-duplicates'}),body:JSON.stringify([{id:String(f.id), lote_id:String(f.loteId), data:f.dataUrl, ts:f.ts||Date.now(), deleted:false}])}); }catch(e){} }
async function supaFotoDelete(id){ try{ await fetch(SUPA_FOTOS+'?id=eq.'+encodeURIComponent(String(id)),{method:'PATCH',headers:supaHeaders(),body:JSON.stringify({deleted:true})}); }catch(e){} }
async function fotoSyncLote(loteId){
  if(!loteId) return;
  try{
    const res=await fetch(SUPA_FOTOS+'?select=id,ts,deleted&lote_id=eq.'+encodeURIComponent(String(loteId)),{headers:supaHeaders()});
    if(!res.ok) return;
    const remote=await res.json();
    const localList=await fotoList(loteId);
    const localIds={}; localList.forEach(f=>localIds[f.id]=true);
    const remoteIds={};
    for(const rf of remote){
      remoteIds[rf.id]=true;
      if(rf.deleted){ if(localIds[rf.id]) await fotoDel(rf.id); continue; }
      if(!localIds[rf.id]){
        const r2=await fetch(SUPA_FOTOS+'?select=data,ts&id=eq.'+encodeURIComponent(rf.id),{headers:supaHeaders()});
        if(r2.ok){ const d=await r2.json(); if(d[0]&&d[0].data){ await fotoPutRaw(rf.id, loteId, d[0].data, rf.ts||d[0].ts); } }
      }
    }
    for(const lf of localList){ if(!remoteIds[lf.id]) supaFotoPush(lf); }
  }catch(e){}
}
function compressImg(file,maxDim,q){
  return new Promise((res)=>{
    const url=URL.createObjectURL(file); const img=new Image();
    img.onload=()=>{ let w=img.width,h=img.height; const m=Math.max(w,h); if(m>maxDim){ const k=maxDim/m; w=Math.round(w*k); h=Math.round(h*k); } const c=document.createElement('canvas'); c.width=w; c.height=h; c.getContext('2d').drawImage(img,0,0,w,h); URL.revokeObjectURL(url); res(c.toDataURL('image/jpeg',q||0.72)); };
    img.onerror=()=>{ URL.revokeObjectURL(url); res(null); };
    img.src=url;
  });
}
function loteLabel(){ return (currentMeta&&currentMeta.loteMain)||'sem-lote'; }
async function updatePhCount(){ const el=document.getElementById('phCount'); if(!el){return;} if(!currentId){ el.classList.remove('on'); return; } try{ const n=(await fotoList(currentId)).length; el.textContent=n; el.classList.toggle('on', n>0); }catch(e){} }
async function openFotos(){ if(!currentId) return; document.getElementById('fotosLote').textContent=loteLabel(); document.getElementById('fotosModal').classList.remove('hidden'); document.body.classList.add("cam-open"); await renderFotos(); fotoSyncLote(currentId).then(()=>renderFotos()); }
function closeFotos(){ document.getElementById('fotosModal').classList.add('hidden'); document.body.classList.remove('cam-open'); }
async function renderFotos(){
  const grid=document.getElementById('fotosGrid'); if(!grid) return;
  const fotos=await fotoList(currentId);
  if(!fotos.length){ grid.innerHTML='<div class="fotos-empty">Nenhuma foto ainda.<br>Toque em <b>Tirar / adicionar foto</b> para registrar a carga do caminhão.</div>'; updatePhCount(); return; }
  grid.innerHTML=fotos.map((f,i)=>`<div class="foto-card"><img src="${f.dataUrl}" alt="foto ${i+1}"><span class="foto-n">${i+1}</span><button class="foto-del" type="button" onclick="EXP.delFoto('${f.id}')" aria-label="Excluir">✕</button></div>`).join('');
  updatePhCount();
}
async function delFoto(id){ await fotoDel(id); supaFotoDelete(id); await renderFotos(); }
async function handleFotos(files){
  if(!files||!files.length) return;
  let n=0;
  for(const f of files){ if(!f.type||!f.type.startsWith('image/')) continue; const d=await compressImg(f,1600,0.72); if(d){ await fotoAdd(currentId,d); n++; } }
  await renderFotos();
  if(n) banner('ok','📷','Foto registrada', n+' foto(s) salva(s) neste lote');
}
function b64ToBlob(d){ const [h,b]=d.split(','); const mime=(h.match(/:(.*?);/)||[])[1]||'image/jpeg'; const bin=atob(b); const u8=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i); return new Blob([u8],{type:mime}); }
function dlBlob(blob,name){ const u=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=u; a.download=name; document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(u),2000); }
function csvCell(v){ v=(v==null?'':String(v)); return /[";\n\r]/.test(v) ? '"'+v.replace(/"/g,'""')+'"' : v; }
function statusTxt(s){ return s==='conferido'?'Conferido':(s==='separado'?'Separado':'Pendente'); }
async function exportRomaneio(){
  if(!items||!items.length){ banner('warn','⚠️','Nada para exportar','Abra um romaneio primeiro'); return; }
  const rows=[['Item','Descrição','Etiqueta','Quantidade','Saldo a mais','Status']];
  items.forEach(it=>{
    const desc=it.descricao||'';
    if(it.etiqueta){
      rows.push([it.num, desc, it.etiqueta, (it.qtd||fmtNum(it.qtdNum||0)), (it.saldo?fmtNum(it.saldo):''), statusTxt(it.status)]);
    } else {
      const tags=it.tags||[];
      if(!tags.length){ rows.push([it.num, desc, '(sem etiqueta)', (it.qtd||fmtNum(it.qtdNum||0)), '', 'Pendente']); }
      tags.forEach(t=>rows.push([it.num, desc, t.tag, fmtNum(t.q), '', t.conf?'Conferida':'Separada']));
    }
  });
  const csv='\ufeff'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});
  const lbl=loteLabel();
  const name='romaneio-'+String(lbl).replace(/[^\w.-]+/g,'_')+'.csv';
  try{ const file=new File([blob],name,{type:'text/csv'}); if(navigator.canShare && navigator.canShare({files:[file]})){ await navigator.share({files:[file], title:'Romaneio '+lbl}); return; } }
  catch(e){ if(e&&e.name==='AbortError') return; }
  dlBlob(blob,name); banner('ok','📄','Romaneio exportado',name);
}
async function fotosExtract(){
  const fotos=await fotoList(currentId); if(!fotos.length){ banner('warn','','Sem fotos','Tire ao menos uma foto primeiro'); return; }
  const lbl=loteLabel().replace(/[^\w.-]/g,'_');
  if(typeof JSZip!=='undefined'){
    try{ const zip=new JSZip(); fotos.forEach((f,i)=>zip.file('carga-'+lbl+'-'+String(i+1).padStart(2,'0')+'.jpg', f.dataUrl.split(',')[1], {base64:true})); const blob=await zip.generateAsync({type:'blob'}); dlBlob(blob,'carga-lote-'+lbl+'.zip'); banner('ok','','Fotos extraídas', fotos.length+' foto(s) em .zip'); return; }catch(e){}
  }
  fotos.forEach((f,i)=>dlBlob(b64ToBlob(f.dataUrl),'carga-'+lbl+'-'+(i+1)+'.jpg'));
  banner('ok','','Fotos baixadas', fotos.length+' arquivo(s)');
}
async function fotosShare(){
  const fotos=await fotoList(currentId); if(!fotos.length){ banner('warn','','Sem fotos','Tire ao menos uma foto primeiro'); return; }
  try{ const files=fotos.map((f,i)=>new File([b64ToBlob(f.dataUrl)],'carga-'+(i+1)+'.jpg',{type:'image/jpeg'})); if(navigator.canShare && navigator.canShare({files})){ await navigator.share({files,title:'Fotos da carga · Lote '+loteLabel()}); return; } }catch(e){ if(e&&e.name==='AbortError') return; }
  banner('warn','','Compartilhar indisponível','Use Extrair (.zip) para baixar as fotos');
}

/* ---------------- MODAIS (prompt/confirm próprios) ---------------- */
let _uiCb=null;
function showUi(){ document.getElementById('uiModal').classList.remove('hidden'); }
function hideUi(){ document.getElementById('uiModal').classList.add('hidden'); _uiCb=null; }
function uiPrompt(title, msg, value, okLabel, mode, cb){
  document.getElementById('uiTitle').textContent=title;
  const mp=document.getElementById('uiMsg'); mp.textContent=msg||''; mp.style.display=msg?'block':'none';
  const inp=document.getElementById('uiInput'); inp.classList.remove('hidden'); inp.value=value||'';
  inp.setAttribute('inputmode', mode==='num'?'decimal':'text');
  document.getElementById('uiOk').textContent=okLabel||'Salvar';
  _uiCb=(ok)=>{ if(ok && cb) cb(inp.value); };
  showUi(); setTimeout(()=>{try{inp.focus();inp.select();}catch(e){}},60);
}
function uiConfirm(title, msg, okLabel, cb){
  document.getElementById('uiTitle').textContent=title;
  const mp=document.getElementById('uiMsg'); mp.textContent=msg||''; mp.style.display=msg?'block':'none';
  document.getElementById('uiInput').classList.add('hidden');
  document.getElementById('uiOk').textContent=okLabel||'Confirmar';
  _uiCb=(ok)=>{ if(ok && cb) cb(); };
  showUi();
}

/* ---------------- ADMIN ---------------- */
function openAdmModal(){
  const m=document.getElementById('admModal'); if(!m) return;
  m.classList.remove('hidden'); document.getElementById('admErr').classList.add('hidden');
  const p=document.getElementById('admPass'); p.value=''; setTimeout(()=>{try{p.focus();}catch(e){}},60);
}
function closeAdmModal(){ const m=document.getElementById('admModal'); if(m) m.classList.add('hidden'); }
function tryAdmin(){
  if(typeof isSuper==='function'&&isSuper()){ adminMode=true; document.body.classList.add('admin'); closeAdmModal(); updateAdminUI(); banner('ok','','Acesso liberado','Sessão de administrador confirmada'); }
  else { document.getElementById('admErr').classList.remove('hidden'); banner('warn','','Acesso restrito','Entre com uma conta administradora do WMS'); }
}
function toggleAdmin(){
  if(adminMode){ adminMode=false; document.body.classList.remove('admin'); updateAdminUI(); banner('warn','','Bloqueado','Edição e exclusão desativadas'); }
  else openAdmModal();
}
function updateAdminUI(){
  const t=document.getElementById('expBtn'); if(t){ t.classList.toggle('on', adminMode); t.textContent = 'Expedição'; }
  renderItems(); try{ renderLotes(); }catch(e){}
}
function admEditTag(num){
  if(!expAdminAllowed(true)) return;
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  uiPrompt('Editar etiqueta','A etiqueta começa com T (ex: T40364663)', it.etiqueta||'', 'Salvar','text', (v)=>{
    let tag=(v||'').trim().toUpperCase(); const m=tag.match(/T\s*\d{4,12}/i); if(m) tag=m[0].replace(/\s+/g,'');
    if(!/^T\d{4,12}$/i.test(tag)){ beep('err'); banner('err','⛔','Etiqueta inválida','Deve começar com T'); return; }
    const anterior=it.etiqueta||'',statusAnterior=it.status; it.etiqueta=tag; it.manualTag=true; it.status='pendente'; auditEvent('etiqueta_editada','Item #'+num+' · '+anterior+' → '+tag+' · processo reiniciado de '+statusAnterior+' para pendente.'); renderItems(); updateProgress();
    banner('ok','✓','Etiqueta alterada',`<span class="mono">${tag}</span>`);
  });
}
function admEditQty(num){
  if(!expAdminAllowed(true)) return;
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  const cur=it.qtd||fmtNum(it.qtdNum||0);
  uiPrompt('Alterar Qtd. Produto','Quantidade total do item', cur, 'Salvar','num', (v)=>{
    const n=parseNum(v); if(n<=0){ beep('err'); banner('err','⛔','Quantidade inválida',''); return; }
    const anterior=it.qtdNum||0,statusAnterior=it.status; it.qtdNum=n; it.qtd=fmtNum(n); if(it.etiqueta)it.status='pendente';else{(it.tags||[]).forEach(t=>t.conf=false);it.forceDone=false;recalcItem(it);} auditEvent('quantidade_editada','Item #'+num+' · '+anterior+' → '+n+' · processo reiniciado de '+statusAnterior+' para '+it.status+'.'); renderItems(); updateProgress();
    banner('ok','✓','Quantidade alterada',`Qtd. Produto: ${it.qtd}`);
  });
}
function admDelItem(num){
  if(!expAdminAllowed(true)) return;
  const it=items.find(i=>String(i.num)===String(num)); if(!it) return;
  uiConfirm('Excluir item','Excluir o item #'+num+'? '+(it.descricao||''), 'Excluir', ()=>{
    auditEvent('item_excluido_confirmado','Item #'+num+' · '+(it.etiqueta||it.descricao||'')+'.'); items=items.filter(i=>String(i.num)!==String(num)); renderItems(); updateProgress();
    banner('warn','✓','Item excluído','#'+num);
  });
}
function admResetItem(num){
  if(!expAdminAllowed(true)) return;
  const it=items.find(i=>String(i.num)===String(num));if(!it)return;
  uiConfirm('Voltar processo','Reabrir separação e conferência do item #'+num+'? O histórico será preservado.','Reabrir',()=>{
    const anterior=it.status||'pendente';
    if(it.etiqueta)it.status='pendente';else{(it.tags||[]).forEach(t=>t.conf=false);it.forceDone=false;recalcItem(it);}
    auditEvent('processo_reaberto','Item #'+num+' · '+(it.etiqueta||'etiquetas por quantidade')+' · '+anterior+' → '+it.status+'.');
    syncActive();renderItems();updateProgress();banner('warn','↶','Processo reaberto','Item #'+num+' voltou para '+it.status);
  });
}
function admEditLote(){
  if(!expAdminAllowed(true)) return;
  const loteAntigo=String(currentMeta.loteMain||''),destAntigo=String(currentMeta.destMain||'');
  uiPrompt('Alterar lote','Número do lote',loteAntigo,'Continuar','text',novoLote=>{
    novoLote=String(novoLote||'').trim();if(!novoLote){banner('err','⛔','Lote inválido','Informe o número do lote');return;}
    uiPrompt('Alterar destino','Destino do romaneio',destAntigo,'Salvar','text',novoDestino=>{
      novoDestino=String(novoDestino||'').trim().toUpperCase();if(!novoDestino){banner('err','⛔','Destino inválido','Informe o destino');return;}
      currentMeta.loteMain=novoLote;currentMeta.destMain=novoDestino;(items||[]).forEach(it=>{it.lote=novoLote;it.destino=novoDestino;});
      auditEvent('lote_destino_editados','Lote '+loteAntigo+' → '+novoLote+' · destino '+destAntigo+' → '+novoDestino+'.');
      syncActive();renderHeader(currentMeta);updateProgress();banner('ok','✓','Lote atualizado',novoLote+' · '+novoDestino);
    });
  });
}

/* ---------------- SCAN LOGIC ---------------- */
function norm(s){ return (s||'').toUpperCase().replace(/[^A-Z0-9]/g,''); }
function digits(s){ return (s||'').replace(/\D/g,''); }

function extractTag(s){
  if(!s) return '';
  const m = String(s).match(/T\s*\d{5,12}/i);   // ETIQUETA dentro do QR (ex: T40364663)
  return m ? m[0].replace(/\s+/g,'').toUpperCase() : '';
}
function matchItem(scanned){
  if(!scanned) return null;
  const ns = norm(scanned);
  const tag = extractTag(scanned);
  const nt = tag ? norm(tag) : '';
  let it = items.find(i=> i.etiqueta && (norm(i.etiqueta)===ns || (nt && norm(i.etiqueta)===nt)));
  if(!it){
    const d = digits(tag || scanned);
    if(d && d.length>=5) it = items.find(i=> i.etiqueta && digits(i.etiqueta)===d);
  }
  return it;
}

function process(scanned){
  const cr=romaneios.find(x=>String(x.id)===String(currentId));if(cr&&cr.cancelado){banner('warn','🔒','Lote cancelado','Este romaneio está disponível somente para consulta');return;}
  if(!scanned) return;
  const now=Date.now();
  if(scanned===lastScan.val && now-lastScan.t<2500) return; // debounce
  lastScan={val:scanned, t:now};

  if(camTarget!==null){
    const target=items.find(i=>String(i.num)===camTarget);
    if(target && !target.etiqueta){
      const tag=extractTag(scanned);
      if(!tag){ beep('err'); vibrate('err'); banner('err','⛔','Etiqueta inválida','A etiqueta começa com T (ex: T40364663)'); return; }
      const ex=(target.tags||[]).find(t=>t.tag===tag);
      if(mode==='conf'){
        // CONFERÊNCIA etiqueta por etiqueta (item de vários códigos)
        if(!ex){ beep('err'); vibrate('err'); banner('err','⛔','Etiqueta não separada',`<span class="mono">${tag}</span> não foi separada neste item`); return; }
        if(ex.conf){ beep('err'); banner('warn','↺','Já conferida',`<span class="mono">${tag}</span> já estava conferida`); return; }
        ex.conf=true; auditEvent('bip_conferencia','Item #'+target.num+' · '+tag+'.'); beep('conf'); vibrate('conf');
        const tt=target.tags||[]; const faltam=tt.filter(t=>!t.conf).length;
        const sepOk=(target.qtdNum>0 && target.feito>=target.qtdNum-0.001);
        if(faltam===0 && sepOk){ banner('ok','✅','Item conferido',`#${target.num} · todas as etiquetas confirmadas`); }
        else { banner('ok','✓','Etiqueta conferida',`<span class="mono">${tag}</span> confere · faltam ${faltam}`); }
        syncActive(); renderItems(); updateProgress();
        return;
      }
      if(awaitingQty) return;                          // ja esperando a quantidade
      if(ex){ beep('err'); banner('warn','↺','Já adicionada',`${tag} já está neste item`); return; }
      awaitingQty=true; pendingTag=tag;
      document.getElementById('cqTag').textContent=tag;
      const cq=document.getElementById('camQty'); cq.classList.remove('hidden');
      const ci=document.getElementById('cqInput'); ci.value=''; setTimeout(()=>{try{ci.focus();}catch(e){}},60);
      beep('sep'); vibrate('sep');
      return;
    }
    camTarget=null;
  }

  const it=matchItem(scanned);
  if(!it){
    beep('err'); vibrate('err');
    const shown = extractTag(scanned) || (scanned||'').slice(0,26);
    banner('err','⛔','Etiqueta não confere',
      `<span class="mono">${shown}</span> não pertence a este romaneio`);
    return;
  }

  if(mode==='sep'){
    if(it.status==='pendente'){
      it.status='separado'; beep('sep'); vibrate('sep');
      auditEvent('bip_separacao','Item #'+it.num+' · '+it.etiqueta+'.');
      banner('sep','📦','Separado',`<span class="mono">${it.etiqueta}</span> · ${it.descricao||''}`);
    } else if(it.status==='separado'){
      beep('err');
      banner('warn','↺','Já separado · falta CONFERIR',`Toque em <b>CONFERIR</b> (verde) no topo e bipe de novo`);
    } else {
      beep('err');
      banner('warn','✓','Já concluído',`<span class="mono">${it.etiqueta}</span> já conferido`);
    }
  } else { // conf
    if(it.status==='separado'){
      it.status='conferido'; beep('conf'); vibrate('conf');
      auditEvent('bip_conferencia','Item #'+it.num+' · '+it.etiqueta+'.');
      banner('ok','✅','Conferido',`<span class="mono">${it.etiqueta}</span> · confere com o romaneio`);
    } else if(it.status==='pendente'){
      beep('err'); vibrate('err');
      banner('err','⚠️','Separe primeiro',`<span class="mono">${it.etiqueta}</span> ainda não foi separado`);
    } else {
      beep('err');
      banner('warn','✓','Já conferido',`<span class="mono">${it.etiqueta}</span> já estava conferido`);
    }
  }
  syncActive(); renderItems(); updateProgress();
}

/* ---------------- CAMERA ---------------- */
async function startCamera(){
  const fmts = [
    Html5QrcodeSupportedFormats.QR_CODE,
    Html5QrcodeSupportedFormats.CODE_128, Html5QrcodeSupportedFormats.CODE_39,
    Html5QrcodeSupportedFormats.CODE_93, Html5QrcodeSupportedFormats.ITF,
    Html5QrcodeSupportedFormats.CODABAR, Html5QrcodeSupportedFormats.EAN_13,
    Html5QrcodeSupportedFormats.EAN_8, Html5QrcodeSupportedFormats.UPC_A,
    Html5QrcodeSupportedFormats.UPC_E, Html5QrcodeSupportedFormats.DATA_MATRIX
  ];
  html5Qr = new Html5Qrcode("reader", {
    formatsToSupport: fmts,
    verbose: false,
    experimentalFeatures: { useBarCodeDetectorIfSupported: true }   // leitor nativo do celular (rápido)
  });
  const qbox=(w,h)=>{ const s=Math.floor(Math.min(w,h)*0.85); return {width:s, height:s}; };
  const base = { fps:20, qrbox:qbox, disableFlip:true };
  const hi = { width:{ideal:1920}, height:{ideal:1080} };   // alta resolução = foca e lê QR pequeno
  const onText = txt=>process(txt), onErr=()=>{};
  let ok=false;
  // 1) câmera TRASEIRA da lista + alta resolução
  try{
    const cams = await Html5Qrcode.getCameras();
    if(cams && cams.length){
      const back = cams.find(c=>/back|rear|traseira|tras|environment/i.test(c.label||'')) || cams[cams.length-1];
      await html5Qr.start(back.id, { ...base, videoConstraints:{ deviceId:{exact:back.id}, ...hi } }, onText, onErr);
      ok=true;
    }
  }catch(e){}
  // 2) traseira por facingMode + alta resolução
  if(!ok){ try{ await html5Qr.start({facingMode:{ideal:"environment"}}, { ...base, videoConstraints:{ facingMode:{ideal:"environment"}, ...hi } }, onText, onErr); ok=true; }catch(e){} }
  // 3) traseira simples
  if(!ok){ try{ await html5Qr.start({facingMode:"environment"}, base, onText, onErr); ok=true; }catch(e){} }
  // 4) última tentativa: frontal
  if(!ok){ try{ await html5Qr.start({facingMode:"user"}, base, onText, onErr); ok=true; }catch(e){} }
  if(!ok){
    const cs=document.getElementById('camStatus');
    if(cs){
      cs.className='cam-status err show';
      cs.innerHTML='<span class="csi">⛔</span><span class="cst"><b>Câmera bloqueada</b><small>Toque no cadeado 🔒 ao lado do endereço, ative a Câmera e abra o leitor de novo.</small></span>';
    }
    return;
  }
  // foco contínuo, se o aparelho suportar (ajuda a focar rápido)
  try{
    const caps = html5Qr.getRunningTrackCapabilities ? html5Qr.getRunningTrackCapabilities() : null;
    if(caps && Array.isArray(caps.focusMode) && caps.focusMode.indexOf('continuous')>=0){
      await html5Qr.applyVideoConstraints({ advanced:[{ focusMode:'continuous' }] });
    }
  }catch(e){}
  scanning=true;
  const fr=document.querySelector('.cam-frame'); if(fr) fr.classList.add('live');
}
async function stopCamera(){
  if(html5Qr && scanning){ try{ await html5Qr.stop(); html5Qr.clear(); }catch(e){} }
  scanning=false; html5Qr=null;
  const fr=document.querySelector('.cam-frame'); if(fr) fr.classList.remove('live');
}

/* ---------------- OVERLAY DA CÂMERA ---------------- */
function updateCamCount(){
  const cc=document.getElementById('camCount'); if(!cc) return;
  const total=items.length;
  const sep=items.filter(itemSep).length;
  const conf=items.filter(itemDone).length;
  cc.textContent=(mode==='sep'?sep:conf)+'/'+total;
}
function syncCamMode(){
  const s=document.getElementById('camModeSep'), c=document.getElementById('camModeConf');
  if(s) s.classList.toggle('on', mode==='sep');
  if(c) c.classList.toggle('on', mode==='conf');
  const ov=document.getElementById('camOverlay');
  if(ov){ ov.classList.toggle('m-sep', mode==='sep'); ov.classList.toggle('m-conf', mode==='conf'); }
  updateCamCount();
}
function openCam(num){
  audioCtx = audioCtx || new (window.AudioContext||window.webkitAudioContext)();
  camTarget = (num!==undefined && num!==null && num!=='') ? String(num) : null;
  awaitingQty=false; pendingTag=null;
  const ov=document.getElementById('camOverlay'); if(!ov) return;
  ov.classList.remove('hidden'); document.body.classList.add('cam-open');
  const cs=document.getElementById('camStatus'); if(cs) cs.classList.remove('show');
  document.getElementById('camQty').classList.add('hidden');
  const hint=document.querySelector('.cam-hint');
  if(hint){ hint.style.display = camTarget ? 'none' : 'block'; hint.textContent='Aponte para o QR code da etiqueta'; }
  syncTargetBar();
  lastScan={val:null,t:0}; syncCamMode(); startCamera();
}
function syncTargetBar(){
  const bar=document.getElementById('camTargetBar'), fin=document.getElementById('camFinish');
  const it = camTarget!==null ? items.find(i=>String(i.num)===camTarget) : null;
  if(!bar||!fin) return;
  if(!it || it.etiqueta){ bar.classList.add('hidden'); fin.classList.add('hidden'); return; }
  const meta=it.qtdNum||0, feito=it.feito||0;
  const pct=meta?Math.min(100,Math.round(feito/meta*100)):0;
  const done=meta>0 && feito>=meta-0.001;
  bar.classList.remove('hidden');
  const ib=document.getElementById('ctBar'); ib.style.width=pct+'%'; ib.className=done?'full':'';
  document.getElementById('ctLabel').innerHTML=`Item #${it.num} · Feito <b>${fmtNum(feito)}</b> / ${fmtNum(meta)} (${pct}%)`;
  fin.classList.toggle('hidden', !done);
}
function camAddQty(){
  if(!awaitingQty || camTarget===null) return;
  const it=items.find(i=>String(i.num)===camTarget); if(!it) return;
  const inp=document.getElementById('cqInput'); const q=parseNum(inp.value);
  if(q<=0){ beep('err'); banner('warn','✏️','Falta a quantidade','Digite a quantidade lida na etiqueta'); inp.focus(); return; }
  it.tags=it.tags||[]; it.tags.push({tag:pendingTag, q}); recalcItem(it);
  auditEvent('bip_quantidade','Item #'+it.num+' · '+pendingTag+' · quantidade '+q+'.');
  document.getElementById('camQty').classList.add('hidden');
  awaitingQty=false; pendingTag=null; lastScan={val:null,t:0};
  syncTargetBar(); renderItems(); updateProgress();
  const done=itemSep(it);
  beep(done?'conf':'sep'); vibrate(done?'conf':'sep');
  banner(done?'ok':'sep', done?'✅':'➕', done?'Quantidade atingida':'Quantidade somada', `${fmtNum(it.feito)} / ${fmtNum(it.qtdNum)}`);
}
function camSkipQty(){
  document.getElementById('camQty').classList.add('hidden');
  awaitingQty=false; pendingTag=null; lastScan={val:null,t:0};
}
function closeCam(){
  stopCamera();
  const ov=document.getElementById('camOverlay'); if(ov) ov.classList.add('hidden');
  document.body.classList.remove('cam-open');
  const cq=document.getElementById('camQty'); if(cq) cq.classList.add('hidden');
  const bar=document.getElementById('camTargetBar'); if(bar) bar.classList.add('hidden');
  const fin=document.getElementById('camFinish'); if(fin) fin.classList.add('hidden');
  const hint=document.querySelector('.cam-hint'); if(hint) hint.style.display='block';
  camTarget=null; awaitingQty=false; pendingTag=null;
}

/* ---------------- MODE ---------------- */
function setMode(m){
  mode=m;
  document.getElementById('modeSep').classList.toggle('active', m==='sep');
  document.getElementById('modeConf').classList.toggle('active', m==='conf');
  lastScan={val:null,t:0};
  syncCamMode();
}

/* ---------------- FLOW ---------------- */
function romHash(meta, its){
  const base=[(meta&&meta.loteMain)||'',(meta&&meta.destMain)||'',(meta&&meta.dataRom)||'',(its||[]).map(it=> it.etiqueta || (it.num+':'+(it.descricao||'')) ).join('|')].join('~');
  let h=5381; for(let i=0;i<base.length;i++){ h=((h*33)^base.charCodeAt(i))>>>0; }
  return 'r'+h.toString(36);
}
async function handleFile(file){
  if(!file || file.type!=='application/pdf'){ showParseError('Selecione um arquivo PDF válido.'); return; }
  document.getElementById('parseStatus').classList.remove('hidden');
  document.getElementById('parseError').classList.add('hidden');
  try{
    const {lines, fullText} = await readPdf(file);
    const parsed = parseRomaneio(lines, fullText);
    if(!parsed.items.length){
      showParseError('Nenhuma etiqueta encontrada neste PDF. Verifique se a coluna "Etiqueta" está preenchida (códigos como T30368091).');
      document.getElementById('parseStatus').classList.add('hidden');
      return;
    }
    currentMeta = {loteMain:parsed.loteMain, destMain:parsed.destMain, resp:parsed.resp, dataRom:parsed.dataRom, dataEmb:parsed.dataEmb};
    items = parsed.items;
    const id = romHash(currentMeta, items);
    // carregar de propósito "revive" o romaneio: remove qualquer bloqueio de exclusão antigo
    delete supaDeleted[String(id)];
    let existing = romaneios.find(r=>String(r.id)===String(id));
    if(!existing){
      try{
        const res=await fetch(SUPA_REST+'?select=dados&id=eq.'+encodeURIComponent(id),{headers:supaHeaders()});
        if(res.ok){ const rows=await res.json(); if(rows[0] && rows[0].dados && !rows[0].dados._del && validRomaneio(rows[0].dados)){ existing=rows[0].dados; existing._synced=true; } }
      }catch(e){}
    }
    if(existing){
      /* O PDF é a fonte dos itens. A cópia existente só pode acrescentar progresso; nunca zerar ou esvaziar. */
      const imported={id,meta:currentMeta,items:items,_upd:Date.now()};
      const merged=mergeRemoteRomaneio(imported,existing);
      merged.meta=Object.assign({},existing.meta||{},currentMeta);
      merged._upd=Date.now(); delete merged._del;
      const exIdx=romaneios.findIndex(r=>String(r.id)===String(id));
      if(exIdx>=0) romaneios[exIdx]=merged; else romaneios.push(merged);
      currentId=id; items=merged.items; currentMeta=merged.meta;
    }
    else { romaneios.push({id, meta:currentMeta, items, _upd:Date.now()}); currentId=id; }
    // carimba como recém-carregado para vencer lápide de exclusão antiga no banco
    { const _r=romaneios.find(x=>String(x.id)===String(id)); if(_r){ _r._upd=Date.now(); delete _r._del; } }
    auditEvent('romaneio_importado','PDF importado/reaberto com '+items.length+' item(ns).',id);
    saveStore();
    document.getElementById('parseStatus').classList.add('hidden');
    openWork('sep');
  }catch(err){
    showParseError('Erro ao ler o PDF: '+(err.message||err));
    document.getElementById('parseStatus').classList.add('hidden');
  }
}
function showParseError(msg){
  const e=document.getElementById('parseError'); e.textContent=msg; e.classList.remove('hidden');
  document.getElementById('parseStatus').classList.add('hidden');
}

/* ---- ATUALIZAR (sai etiqueta / entra etiqueta) ---- */
async function handleUpdateFile(file){
  if(!file || file.type!=='application/pdf'){ banner('err','⛔','Arquivo inválido','Selecione um PDF do romaneio'); return; }
  banner('','⏳','Atualizando…','Lendo o novo romaneio');
  try{
    const {lines, fullText} = await readPdf(file);
    const parsed = parseRomaneio(lines, fullText);
    if(!parsed.items.length){ banner('err','⛔','Sem etiquetas','Nenhuma etiqueta encontrada no PDF'); return; }
    const changes = mergeRomaneio(parsed.items);
    const ativo=romaneios.find(x=>String(x.id)===String(currentId));
    if(ativo){const d=[];changes.changedTag.forEach(x=>d.push('Etiqueta diferente no PDF atualizado: '+x+'. A etiqueta existente foi preservada.'));changes.removed.forEach(x=>d.push('Item '+x+' não veio no PDF atualizado e foi preservado.'));ativo._divergencias=[...new Set([...(ativo._divergencias||[]),...d])];}
    auditEvent('romaneio_atualizado','PDF atualizado: '+changes.entered.length+' entrada(s), '+changes.removed.length+' item(ns) preservado(s).');
    currentMeta = {loteMain:parsed.loteMain, destMain:parsed.destMain, resp:parsed.resp, dataRom:parsed.dataRom, dataEmb:parsed.dataEmb};
    renderLotes(); renderHeader(currentMeta);
    renderItems(); updateProgress(); renderDivergencePanel();
    renderUpdateSummary(changes);
    // limpa selo "nova" depois de um tempo
    clearTimeout(window._novaTimer);
    window._novaTimer = setTimeout(()=>{ items.forEach(i=>i.isNew=false); renderItems(); }, 25000);
    window.scrollTo(0,0);
  }catch(err){ banner('err','⛔','Erro ao ler','Não foi possível ler o PDF'); }
}

function mergeRomaneio(newItems){
  const oldByNum={}; items.forEach(i=>oldByNum[i.num]=i);
  const newNums=new Set(newItems.map(i=>i.num));
  const entered=[], gotTag=[], changedTag=[];
  const merged=newItems.map(ni=>{
    const old=oldByNum[ni.num];
    if(!old){ entered.push(ni.etiqueta||('#'+ni.num)); return {...ni, isNew: !!ni.etiqueta}; }
    let status=old.status, etiqueta=old.etiqueta, manualTag=old.manualTag, isNew=false;
    let tags=old.tags||[];
    if(ni.etiqueta){
      if(!etiqueta){ etiqueta=ni.etiqueta; manualTag=false; status='pendente'; isNew=true; gotTag.push(ni.etiqueta); }
      else if(norm(etiqueta)!==norm(ni.etiqueta)){ // divergência: preserva o valor já trabalhado
        changedTag.push(etiqueta+' ≠ '+ni.etiqueta);
      }
    }
    const m={...ni, etiqueta, status, manualTag, isNew, tags};
    if(!etiqueta){   // item sem etiqueta: preserva quantidades ja somadas
      m.feito=(tags||[]).reduce((s,t)=>s+(t.q||0),0);
      m.status=(m.qtdNum>0 && m.feito>=m.qtdNum-0.001)?'separado':(m.feito>0?'parcial':'aguardando');
    }
    return m;
  });
  const removed=items.filter(i=>!newNums.has(i.num));
  const removedDone=removed.filter(i=>i.status==='separado'||i.status==='conferido');
  /* Item ausente no PDF atualizado continua no lote até exclusão manual confirmada. */
  const preserved=removed.map(i=>Object.assign({},i,{_retained:true}));
  items=merged.concat(preserved).sort((a,b)=>(+a.num)-(+b.num));
  return {entered, gotTag, changedTag,
    removed:removed.map(i=>i.etiqueta||('#'+i.num)),
    removedDone:removedDone.map(i=>i.etiqueta||('#'+i.num))};
}

function renderUpdateSummary(c){
  const el=document.getElementById('updateSummary');
  const nada = !c.entered.length && !c.removed.length && !c.gotTag.length && !c.changedTag.length;
  let rows='';
  if(nada){
    rows=`<div class="upd-row"><span class="v">Nenhuma mudança de etiqueta. Progresso mantido.</span></div>`;
  }else{
    if(c.gotTag.length)    rows+=`<div class="upd-row"><span class="k">Ganharam etiq.</span><span class="v"><span class="mono">${c.gotTag.join(', ')}</span></span></div>`;
    if(c.entered.length)   rows+=`<div class="upd-row"><span class="k">Entraram</span><span class="v"><span class="mono">${c.entered.join(', ')}</span></span></div>`;
    if(c.changedTag.length)rows+=`<div class="upd-row"><span class="k">Divergências</span><span class="v">Etiqueta existente preservada: <span class="mono">${c.changedTag.join(', ')}</span></span></div>`;
    if(c.removed.length)   rows+=`<div class="upd-row"><span class="k">Preservados</span><span class="v">Não vieram no PDF novo e foram mantidos: <span class="mono">${c.removed.join(', ')}</span></span></div>`;
    if(c.removedDone.length)rows+=`<div class="upd-row alert"><span class="k">Protegidos</span><span class="v">Itens já bipados continuam intactos: <span class="mono">${c.removedDone.join(', ')}</span></span></div>`;
  }
  el.className='upd-card';
  el.innerHTML=`<div class="ut">Romaneio atualizado <span class="ux" onclick="this.closest('.upd-card').classList.add('hidden')">×</span></div>${rows}`;
  el.classList.remove('hidden');
  beep('conf'); vibrate('sep');
}

