 window.abrirAlertas=function(){var as=dados(),ativos=as.filter(function(a){return a.n>0;});openDrawer('Central de Alertas','<div style="color:var(--muted);font-size:.76rem;margin:-4px 0 14px">Atualização automática · '+new Date().toLocaleString('pt-BR')+'</div><div class="alert-list">'+(ativos.length?ativos.map(function(a){return '<div class="alert-row" style="--ac:'+a.cor+'"><div class="alert-row-top"><b>'+a.titulo+'</b><em>'+a.n+'</em></div><p>'+a.desc+'</p><button class="gbtn" data-alert-view="'+a.view+'" style="margin-top:10px;padding:6px 10px">Ver detalhes</button></div>';}).join(''):'<div class="ha-ok">Tudo certo. Nenhum alerta operacional neste momento.</div>')+'</div>');document.querySelectorAll('[data-alert-view]').forEach(function(b){b.onclick=function(){closeDrawer();go(b.dataset.alertView);};});};
 var top=document.querySelector('.topbar'),user=document.getElementById('userBtn');if(top&&user&&!document.getElementById('alertTop')){var bt=document.createElement('button');bt.id='alertTop';bt.className='alertTop';bt.title='Central de Alertas';bt.innerHTML='⚠<span class="ab"></span>';bt.onclick=window.abrirAlertas;top.insertBefore(bt,user);}
