(function(){
 var s=document.createElement('style');s.textContent='#v-vsm .vrHead{display:flex;justify-content:space-between;gap:20px;align-items:flex-end;margin-bottom:16px}.vrHead h1{font-size:1.7rem;margin:3px 0}.vrHead p{margin:0;color:#64748b;font-size:.78rem}.vrLive{background:#e8f8ef;color:#128043;border:1px solid #bce9cd;border-radius:99px;padding:8px 12px;font-size:.67rem;font-weight:900;white-space:nowrap}.vrLive:before{content:"";display:inline-block;width:7px;height:7px;background:#18b45b;border-radius:50%;margin-right:7px}.vrKpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.vrKpi{background:#fff;border:1px solid #dce3ec;border-radius:14px;padding:15px 17px;box-shadow:0 5px 16px rgba(15,32,57,.05)}.vrKpi span{font-size:.59rem;letter-spacing:.08em;text-transform:uppercase;color:#718096;font-weight:900}.vrKpi b{display:block;font-size:1.4rem;margin:5px 0 2px;color:#102039}.vrKpi small{font-size:.63rem;color:#8b98aa}.vrMap{background:#fff;border:1px solid #dce3ec;border-radius:18px;padding:20px;box-shadow:0 8px 24px rgba(15,32,57,.06)}.vrMapTop{display:flex;justify-content:space-between;align-items:center;padding-bottom:13px;border-bottom:1px solid #e4e9f0}.vrMapTop b{font-size:.82rem}.vrMapTop span{font-size:.63rem;color:#718096}.vrGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:34px 38px;padding:22px 0 10px}.vrStep{position:relative;border:1px solid #dbe3ec;border-radius:14px;padding:16px 17px;background:#fbfcfe;min-height:132px;border-top:4px solid var(--vc)}.vrStep:not(:nth-child(3n)):after{content:"";position:absolute;right:-30px;top:62px;width:21px;height:2px;background:#9aa8ba}.vrStep:not(:nth-child(3n)):before{content:"";position:absolute;right:-31px;top:58px;border:5px solid transparent;border-left-color:#9aa8ba}.vrNum{font-size:.56rem;color:var(--vc);letter-spacing:.1em;font-weight:900}.vrStep h3{font-size:.92rem;margin:6px 0 3px}.vrStep>p{font-size:.65rem;color:#718096;margin:0 0 13px}.vrStat{display:flex;justify-content:space-between;align-items:flex-end;border-top:1px solid #e5eaf0;padding-top:10px}.vrStat b{font-size:1.25rem}.vrStat small{text-align:right;font-size:.59rem;color:#718096}.vrBar{height:5px;border-radius:8px;background:#e8edf3;margin-top:10px;overflow:hidden}.vrBar i{display:block;height:100%;background:var(--vc);border-radius:8px}.vrFoot{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:15px}.vrPanel{background:#fff;border:1px solid #dce3ec;border-radius:15px;padding:16px 18px}.vrPanel h3{font-size:.78rem;margin:0 0 9px}.vrRow{display:flex;gap:9px;padding:9px 0;border-top:1px solid #e7ebf1;font-size:.66rem}.vrDot{width:8px;height:8px;border-radius:50%;background:var(--vd);margin-top:3px;flex:none}.vrRow b{display:block}.vrRow small{display:block;color:#8996a7;margin-top:2px}@media(max-width:1050px){.vrGrid{grid-template-columns:1fr 1fr}.vrStep:after,.vrStep:before{display:none}.vrKpis{grid-template-columns:1fr 1fr}}@media(max-width:700px){.vrGrid,.vrFoot,.vrKpis{grid-template-columns:1fr}.vrHead{align-items:flex-start}.vrMap{padding:13px}}';document.head.appendChild(s);
 function safeArr(v){return Array.isArray(v)?v:[]}
 function safeObj(v){return v&&typeof v==='object'?v:{}}
 function vrWhen(v){if(!v)return 'sem data';var z=new Date(v);return isNaN(z.getTime())?String(v):z.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}
 function vrData(){var et=Object.keys(safeObj(typeof ETQ==='undefined'?{}:ETQ)).map(function(k){return ETQ[k]||{}}),st=safeArr(typeof STAGE==='undefined'?[]:STAGE),slots=safeArr(typeof S==='undefined'?[]:S),moves=safeArr(typeof MV==='undefined'?[]:MV),wh=(typeof cfg!=='undefined'&&cfg)?cfg.warehouse:null,occ=slots.filter(function(x){return x&&x.o&&(!wh||x.w===wh)}),today=new Date().toDateString(),out=moves.filter(function(x){return x&&x.action==='saida'&&new Date(x.at).toDateString()===today}),old=st.filter(function(x){return x&&x.at&&Date.now()-Date.parse(x.at)>14400000}).length;return{et:et,ger:et.filter(function(x){return x.status==='gerada'}).length,rec:et.filter(function(x){return x.status==='entrada'}).length,st:st,occ:occ,out:out,old:old,moves:moves,docs:Object.keys(safeObj(typeof NFS==='undefined'?{}:NFS)).length+Object.keys(safeObj(typeof ROMS==='undefined'?{}:ROMS)).length,kg:st.reduce(function(a,x){return a+(Number(x.pl)||0)},0),slots:slots.length}}
 function vrStep(n,t,d,v,sub,p,c){return '<div class="vrStep" style="--vc:'+c+'"><div class="vrNum">ETAPA '+n+'</div><h3>'+t+'</h3><p>'+d+'</p><div class="vrStat"><b>'+v+'</b><small>'+sub+'</small></div><div class="vrBar"><i style="width:'+Math.max(3,Math.min(100,p))+'%"></i></div></div>'}
 window.renderVSMLean=function(){var el=document.getElementById('v-vsm');if(!el)return;try{var d=vrData(),pr=d.et.length?Math.round(d.rec/d.et.length*100):0,po=d.slots?Math.round(d.occ.length/d.slots*100):0,alerts=[];if(d.old)alerts.push(['#dc2626',d.old+' volumes aguardando há mais de 4 horas','Priorizar endereçamento ou decisão operacional.']);if(d.ger)alerts.push(['#e67e00',d.ger+' etiquetas aguardando recebimento','Documentos disponíveis para conferência.']);if(po>=90)alerts.push(['#dc2626','Capacidade do armazém em nível crítico',po+'% das vagas ocupadas.']);if(!alerts.length)alerts.push(['#18a957','Fluxo operando normalmente','Nenhum gargalo crítico detectado.']);var ev=d.moves.slice(0,6);el.innerHTML='<div class="vrHead"><div><div style="font-size:.6rem;color:#f05a0b;font-weight:900;letter-spacing:.12em">VSM · FLUXO OPERACIONAL</div><h1>Fluxo de Valor em Tempo Real</h1><p>Acompanhamento da entrada fiscal até a expedição do material.</p></div><div class="vrLive">ATUALIZADO '+new Date().toLocaleTimeString('pt-BR')+'</div></div><div class="vrKpis"><div class="vrKpi"><span>Documentos</span><b>'+d.docs+'</b><small>notas e romaneios cadastrados</small></div><div class="vrKpi"><span>Recebimento</span><b>'+pr+'%</b><small>'+d.rec+' etiquetas confirmadas</small></div><div class="vrKpi"><span>Fila intermediária</span><b>'+d.st.length+'</b><small>'+fmt(d.kg)+' kg aguardando</small></div><div class="vrKpi"><span>Ocupação</span><b>'+po+'%</b><small>'+d.occ.length+' posições utilizadas</small></div></div><div class="vrMap"><div class="vrMapTop"><b>Fluxo atual do material</b><span>FORNECEDOR → RECEBIMENTO → ESTOQUE → EXPEDIÇÃO</span></div><div class="vrGrid">'+vrStep('01','Entrada fiscal','NF ou romaneio entra no WMS',d.docs,'documentos','100','#64748b')+vrStep('02','Recebimento','Conferência e bipagem das etiquetas',d.rec,pr+'% concluído',pr,'#2674d9')+vrStep('03','Estoque intermediário','Material recebido aguarda endereço',d.st.length,fmt(d.kg)+' kg',d.st.length?100:3,'#ef9b16')+vrStep('04','Armazenagem','Material enviado para sua posição',d.occ.length,po+'% ocupado',po,'#079f91')+vrStep('05','Requisições','Separação conforme necessidade',0,'fila atual',3,'#7655d9')+vrStep('06','Expedição','Baixa e saída física concluída',d.out.length,'saídas hoje',d.out.length?100:3,'#18a957')+'</div></div><div class="vrFoot"><div class="vrPanel"><h3>Gargalos e prioridades</h3>'+alerts.map(function(x){return '<div class="vrRow" style="--vd:'+x[0]+'"><i class="vrDot"></i><div><b>'+x[1]+'</b><small>'+x[2]+'</small></div></div>'}).join('')+'</div><div class="vrPanel"><h3>Últimas movimentações</h3>'+(ev.length?ev.map(function(x){return '<div class="vrRow" style="--vd:#18a957"><i class="vrDot"></i><div><b>'+String(x.action||'movimentação').toUpperCase()+' · '+(x.pr||x.code||'sem produto')+'</b><small>'+vrWhen(x.at)+' · '+(x.by||'sem usuário')+'</small></div></div>'}).join(''):'<div class="vrRow"><div>Sem movimentações registradas.</div></div>')+'</div></div>'}catch(e){console.error('VSM 4',e);el.innerHTML='<div class="vrHead"><div><h1>Fluxo de Valor em Tempo Real</h1><p>Os dados estão sendo preparados. A tela atualizará automaticamente.</p></div><div class="vrLive">CONECTADO</div></div>'}};
})();

