 function romaneiosHoje(){var h=new Date(),arr=[];try{Object.keys(ROMS||{}).forEach(function(k){var d=ROMS[k]||{},dt=new Date(d.at);if(!isNaN(dt.getTime())&&dt.getFullYear()===h.getFullYear()&&dt.getMonth()===h.getMonth()&&dt.getDate()===h.getDate())arr.push({key:k,doc:d});});}catch(e){}if(!arr.length)return 'Hoje não entrou nenhum romaneio no sistema até o momento.';arr.sort(function(a,b){return Date.parse(b.doc.at||0)-Date.parse(a.doc.at||0);});var etiquetas=0,recebidas=0,users={};arr.forEach(function(o){var ids=[];try{ids=Object.keys(ETQ||{}).filter(function(id){return (ETQ[id]||{}).nf===o.key;});}catch(e){}etiquetas+=ids.length;recebidas+=ids.filter(function(id){var e=ETQ[id]||{};return e.status==='entrada'||(e.hist||[]).some(function(x){return x&&x.ev==='entrada';});}).length;if(o.doc.by)users[o.doc.by]=1;});var linhas=['Romaneios que entraram hoje: '+arr.length,'Etiquetas geradas: '+etiquetas,'Etiquetas recebidas: '+recebidas];if(Object.keys(users).length)linhas.push('Importados por: '+Object.keys(users).join(', '));linhas.push('Romaneios de hoje:');arr.forEach(function(o){linhas.push('• '+(o.doc.nRomaneio||o.key)+' — '+(o.doc.cliente||'cliente não informado')+' · '+dataHora(o.doc.at));});return linhas.join('\n');}
 function movimentosHoje(tipo){var h=new Date(),arr=[];try{arr=(MV||[]).filter(function(m){var d=new Date(m.at);return !isNaN(d.getTime())&&d.getFullYear()===h.getFullYear()&&d.getMonth()===h.getMonth()&&d.getDate()===h.getDate()&&(!tipo||m.action===tipo||(tipo==='entrada'&&m.action==='recebimento'));});}catch(e){}return arr;}
 function resumoMovimentos(tipo){var arr=movimentosHoje(tipo),kg=0,mt=0,users={};arr.forEach(function(m){var u=String(m.u||(typeof unitOf==='function'?unitOf(m.pr):'KG')).toUpperCase(),q=Number(m.q)||0;if(u==='MT')mt+=q;else kg+=q;if(m.by)users[m.by]=1;});var nome=tipo==='saida'?'saídas':tipo==='entrada'?'entradas':'movimentações';if(!arr.length)return 'Não há '+nome+' registradas hoje.';var linhas=['Hoje foram registradas '+arr.length+' '+nome+'.','Total: '+(typeof fmt==='function'?fmt(kg):kg)+' KG'+(mt?' · '+(typeof fmt==='function'?fmt(mt):mt)+' MT':'')];if(Object.keys(users).length)linhas.push('Usuários: '+Object.keys(users).join(', '));linhas.push('Últimos registros:');arr.slice(0,8).forEach(function(m){linhas.push('• '+dataHora(m.at)+' · '+(m.pr||'sem produto')+' · '+(typeof fmt==='function'?fmt(Number(m.q)||0):m.q)+' '+String(m.u||'KG').toUpperCase()+' · '+(m.code||'sem local')+' · '+(m.by||'sem usuário'));});return linhas.join('\n');}
 function entradasHojeDoMaterial(mat){var arr=movimentosHoje('entrada').filter(function(m){return String(m.pr||'')===String(mat.codigo);}),un=typeof unitOf==='function'?unitOf(mat.codigo):'KG',total=arr.reduce(function(s,m){return s+(Number(m.q)||0);},0),ets={},users={};arr.forEach(function(m){if(m.et)ets[m.et]=1;if(m.by)users[m.by]=1;});if(!arr.length)return 'Hoje não houve entrada registrada para o material '+mat.codigo+' — '+mat.descricao+'.';var linhas=['Entradas de hoje para o material consultado:','Produto: '+mat.codigo+' — '+mat.descricao,'Quantidade total: '+(typeof fmt==='function'?fmt(total):total)+' '+un,'Registros de entrada: '+arr.length,'Etiquetas recebidas: '+Object.keys(ets).length];if(Object.keys(users).length)linhas.push('Recebido por: '+Object.keys(users).join(', '));linhas.push('Últimas entradas:');arr.slice(0,8).forEach(function(m){linhas.push('• '+dataHora(m.at)+' · '+(typeof fmt==='function'?fmt(Number(m.q)||0):m.q)+' '+un+' · '+(m.et||'sem etiqueta')+' · '+(m.code||'sem local'));});return linhas.join('\n');}
 function resumoVagas(){var todas=[];try{todas=(S||[]).filter(function(x){return !cfg||!cfg.warehouse||x.w===cfg.warehouse;});}catch(e){}var ocup=todas.filter(function(x){return x.o&&Number(x.q)>0;}),livres=todas.length-ocup.length,pct=todas.length?Math.round(ocup.length/todas.length*100):0;return 'Situação das vagas:\n• Total: '+todas.length+'\n• Ocupadas: '+ocup.length+'\n• Livres: '+livres+'\n• Ocupação: '+pct+'%';}
 function resumoRecebimento(){var pend=[];try{pend=(STAGE||[]).slice();}catch(e){}var kg=0,mt=0,users={};pend.forEach(function(s){var u=typeof unitOf==='function'?unitOf(s.pr):'KG',q=Number(s.pl)||0;if(u==='MT')mt+=q;else kg+=q;if(s.by)users[s.by]=1;});if(!pend.length)return 'O recebimento está em dia: não há materiais aguardando endereço.';return 'Recebimento pendente:\n• '+pend.length+' etiqueta(s) aguardando endereço\n• '+(typeof fmt==='function'?fmt(kg):kg)+' KG'+(mt?'\n• '+(typeof fmt==='function'?fmt(mt):mt)+' MT':'')+(Object.keys(users).length?'\n• Recebidos por: '+Object.keys(users).join(', '):'');}
 function resumoEtiquetas(){var bob=0,rast=0,comPeso=0;try{bob=Object.keys(BOB||{}).length;comPeso=Object.keys(BOB||{}).filter(function(k){return Number((BOB[k]||{}).pl)>0;}).length;rast=Object.keys(ETQ||{}).length;}catch(e){}return 'Etiquetas no sistema:\n• Catálogo de bobinas: '+bob+'\n• Bobinas com quantidade: '+comPeso+'\n• Etiquetas rastreáveis de NF/romaneio: '+rast;}
 function resumoUsuarios(){var arr=[];try{arr=(US||[]).slice();}catch(e){}var ativos=arr.filter(function(u){return u.active!==false;});return 'Usuários cadastrados: '+arr.length+'\nAtivos: '+ativos.length+'\n'+ativos.slice(0,15).map(function(u){return '• '+u.u+' — '+(u.role||'perfil não informado');}).join('\n');}
 function movEntre(inicio,fim,tipo){try{return (MV||[]).filter(function(m){var d=Date.parse(m.at);return d>=inicio.getTime()&&d<fim.getTime()&&(!tipo||m.action===tipo||(tipo==='entrada'&&m.action==='recebimento'));});}catch(e){return [];}}
 function totalMov(arr){var kg=0,mt=0;arr.forEach(function(m){var q=Number(m.q)||0,u=String(m.u||(typeof unitOf==='function'?unitOf(m.pr):'KG')).toUpperCase();if(u==='MT')mt+=q;else kg+=q;});return {n:arr.length,kg:kg,mt:mt};}
 function compararHojeOntem(tipo){var agora=new Date(),h0=new Date(agora.getFullYear(),agora.getMonth(),agora.getDate()),h1=new Date(h0);h1.setDate(h1.getDate()+1);var o0=new Date(h0);o0.setDate(o0.getDate()-1),a=totalMov(movEntre(h0,h1,tipo)),b=totalMov(movEntre(o0,h0,tipo)),nome=tipo==='saida'?'saídas':'entradas',dif=a.n-b.n;return 'Comparação de '+nome+':\nHoje: '+a.n+' registros · '+(typeof fmt==='function'?fmt(a.kg):a.kg)+' KG'+(a.mt?' · '+(typeof fmt==='function'?fmt(a.mt):a.mt)+' MT':'')+'\nOntem: '+b.n+' registros · '+(typeof fmt==='function'?fmt(b.kg):b.kg)+' KG'+(b.mt?' · '+(typeof fmt==='function'?fmt(b.mt):b.mt)+' MT':'')+'\nResultado: hoje houve '+(dif===0?'a mesma quantidade de registros':Math.abs(dif)+' registro(s) a '+(dif>0?'mais':'menos'))+'.';}
 function resumoPeriodo(periodo,tipo){var agora=new Date(),fim=new Date(agora.getTime()+1),ini;if(periodo==='semana'){ini=new Date(agora);ini.setHours(0,0,0,0);ini.setDate(ini.getDate()-6);}else{ini=new Date(agora.getFullYear(),agora.getMonth(),1);}var arr=movEntre(ini,fim,tipo),z=totalMov(arr),nome=tipo==='saida'?'saídas':tipo==='entrada'?'entradas':'movimentações';return 'Resumo de '+nome+' '+(periodo==='semana'?'dos últimos 7 dias':'deste mês')+':\n• Registros: '+z.n+'\n• Total: '+(typeof fmt==='function'?fmt(z.kg):z.kg)+' KG'+(z.mt?'\n• '+(typeof fmt==='function'?fmt(z.mt):z.mt)+' MT':'');}
 function consultaUsuario(pergunta){var l=textoBusca(pergunta),u=null;try{u=(US||[]).find(function(x){return l.indexOf(textoBusca(x.u))>=0;});}catch(e){}if(!u)return null;var hoje=/hoje/.test(l),h=new Date(),arr=[];try{arr=(MV||[]).filter(function(m){if(String(m.by||'').toLowerCase()!==String(u.u||'').toLowerCase())return false;if(!hoje)return true;var d=new Date(m.at);return d.getFullYear()===h.getFullYear()&&d.getMonth()===h.getMonth()&&d.getDate()===h.getDate();}).sort(function(a,b){return Date.parse(b.at)-Date.parse(a.at);});}catch(e){}var z=totalMov(arr),linhas=['Atividade de '+u.u+(hoje?' hoje':' em todo o histórico')+':','Perfil: '+(u.role||'não informado'),'Movimentações: '+z.n,'Volume movimentado: '+(typeof fmt==='function'?fmt(z.kg):z.kg)+' KG'+(z.mt?' · '+(typeof fmt==='function'?fmt(z.mt):z.mt)+' MT':'')];if(arr.length){linhas.push('Últimos registros:');arr.slice(0,10).forEach(function(m){linhas.push('• '+dataHora(m.at)+' · '+(m.action||'movimento')+' · '+(m.pr||'sem produto')+' · '+(typeof fmt==='function'?fmt(Number(m.q)||0):m.q)+' '+String(m.u||'KG').toUpperCase());});}return linhas.join('\n');}
 function buscaEtiqueta(pergunta){var m=String(pergunta||'').toUpperCase().match(/[A-Z0-9]+(?:-[A-Z0-9]+){1,}|\b\d{7,}\b/),et=m?m[0]:ultimaEtiquetaWmsAi;if(!et)return null;var b=(typeof BOB!=='undefined'&&BOB[et])||null,e=(typeof ETQ!=='undefined'&&ETQ[et])||null,mov=[];try{mov=(MV||[]).filter(function(x){return String(x.et||'').toUpperCase()===et;}).sort(function(a,b){return Date.parse(b.at)-Date.parse(a.at);});}catch(_e){}if(!b&&!e&&!mov.length)return 'Não encontrei a etiqueta '+et+'.';ultimaEtiquetaWmsAi=et;ultimoAssuntoWmsAi='etiqueta';var pr=(e&&e.cProd)||(b&&b.pr)||(mov[0]&&mov[0].pr)||'',desc=(e&&e.xProd)||(b&&b.desc)||(typeof descOf==='function'?descOf(pr):'')||'',qtd=Number((e&&e.kg)||(b&&b.pl)||0),qtxt=typeof fmt==='function'?fmt(qtd):String(qtd),linhas=['Etiqueta: '+et,'Produto: '+(pr||'não informado')+(desc?' — '+desc:''),'Quantidade: '+qtxt+' '+(typeof unitOf==='function'?unitOf(pr):'KG')];if(typeof LOC!=='undefined'&&LOC[et])linhas.push('Local atual: '+LOC[et]);if(mov[0])linhas.push('Último movimento: '+(mov[0].action||'movimento')+' em '+dataHora(mov[0].at)+' por '+(mov[0].by||'usuário não registrado'));return linhas.join('\n');}
 function respostaContextual(pergunta){var l=textoBusca(pergunta);
  if(/^(oi|ola|bom dia|boa tarde|boa noite|e ai)/.test(l))return 'Olá! Pergunte sobre qualquer informação registrada no WMS. Posso cruzar produto, NF, etiqueta, vaga, usuário, entrada, saída e recebimento.';
  if(/obrigad|valeu|perfeito|entendi/.test(l))return 'Por nada. Pode continuar perguntando sobre o mesmo item; eu mantenho o contexto da conversa.';
  if(ultimaNfWmsAi&&/(ela|dela|essa nota|essa nf|fornecedor|quem recebeu|o que veio|quais produtos|quando chegou|quantas etiquetas)/.test(l))return relatorioNF(ultimaNfWmsAi.doc,ultimaNfWmsAi.key);
  if(ultimoRomaneioWmsAi&&/(ele|dele|esse romaneio|cliente|quem recebeu|o que veio|quais produtos|quando chegou|quantas etiquetas)/.test(l))return relatorioRomaneio(ultimoRomaneioWmsAi.doc,ultimoRomaneioWmsAi.key);
  if(ultimaEtiquetaWmsAi&&/(ela|dela|essa etiqueta|onde esta|quem bipou|ultimo movimento|qual produto)/.test(l))return buscaEtiqueta('etiqueta '+ultimaEtiquetaWmsAi);
  if(ultimoMaterialWmsAi){if(/(onde|local|vaga|saldo|quanto tem|quantidade|ainda tem|tem dele|tem dela)/.test(l))return saldoMaterialContexto(ultimoMaterialWmsAi);if(/(ultima entrada|ultimo recebimento|quando entrou|quando chegou|quem recebeu)/.test(l))return ultimaEntradaMaterial('material '+ultimoMaterialWmsAi.codigo);if(/(quanto|quantas|qtd|quantidade).*(hoje|entrou|entrada)|entrou hoje/.test(l))return entradasHojeDoMaterial(ultimoMaterialWmsAi);}
  if(/o que (voce|vc) (faz|sabe)|ajuda|comandos|perguntar/.test(l))return 'Exemplos do que posso consultar:\n• “Temos alça 1000 PET?”\n• “Quanto entrou hoje?”\n• “Onde está esse material?”\n• “Quando foi a última entrada?”\n• “NF 40972”\n• “Quantas NFs entraram hoje?”\n• “Onde está a etiqueta T40342487?”\n• “Quantas vagas estão livres?”\n• “Quem fez as entradas de hoje?”';
  return null;
 }
 function resposta(q){var t=String(q||'').trim(),low=t.toLowerCase(),num=numero(t),occ=ocupadas();
  if(!t)return 'Digite uma pergunta para eu ajudar.';
  if(/\d{2,4}\s*[x×]\s*\d{2,4}/i.test(t)||/\bitem\b/i.test(t)&&/\d{2,4}/.test(t))return consultaDisponibilidade(t);
  if(/ajuda|o que voc[eê] faz|como funciona/.test(low))return 'Posso resumir o estoque, mostrar alertas, localizar um material pelo código e consultar uma nota fiscal. Exemplo: “onde está o produto 0303410008?”';
  if(/alerta|problema|pend[eê]ncia/.test(low)){try{var aa=typeof wmsAlertas==='function'?wmsAlertas():[],at=aa.filter(function(a){return a.n>0;});return at.length?'Alertas atuais:\n'+at.map(function(a){return '• '+a.titulo+': '+a.n;}).join('\n'):'Tudo certo: não há alertas operacionais neste momento.';}catch(e){return 'Não consegui consultar os alertas agora.';}}
  if(/(comparar|compara[cç][aã]o|mais.*que|menos.*que).*(hoje|ontem)|(hoje).*(ontem)/.test(low))return compararHojeOntem(/sa[ií]da/.test(low)?'saida':'entrada');
  if(/(semana|7 dias)/.test(low)&&/(entrada|sa[ií]da|movimenta[cç][aã]o)/.test(low))return resumoPeriodo('semana',/sa[ií]da/.test(low)?'saida':/entrada/.test(low)?'entrada':'');
  if(/(este m[eê]s|no m[eê]s|mensal|m[eê]s atual)/.test(low)&&/(entrada|sa[ií]da|movimenta[cç][aã]o)/.test(low))return resumoPeriodo('mes',/sa[ií]da/.test(low)?'saida':/entrada/.test(low)?'entrada':'');
  if(/usu[aá]rio|operador|quem fez|atividade de|movimenta[cç][oõ]es de/.test(low)){var ru=consultaUsuario(t);if(ru)return ru;}
  if(/(quando|qual).*(última|ultima|último|ultimo|vez).*(entrou|entrada|chegou|recebid)|última entrada|ultima entrada/.test(low))return ultimaEntradaMaterial(t);
  if(/(temos|tem |há |ha |existe|saldo).*(bobina|material|produto|pet|tecido|filme|cadar[cç]o|al[cç]a)|(bobina|material|produto|pet|tecido|filme|cadar[cç]o|al[cç]a).*(estoque|temos|existe)/.test(low))return saldoMaterialDescricao(t);
  if(/estoque|resumo|saldo/.test(low)&&!num){var prods={},kg=0,mt=0;occ.forEach(function(x){if(x.pr)prods[x.pr]=1;var u=(typeof unitOf==='function'?unitOf(x.pr):'KG'),v=Number(x.q)||0;if(u==='MT')mt+=v;else kg+=v;});return 'Resumo atual do estoque:\n• '+occ.length+' posições ocupadas\n• '+Object.keys(prods).length+' produtos distintos\n• '+(typeof fmt==='function'?fmt(kg):kg.toLocaleString('pt-BR'))+' kg\n• '+(typeof fmt==='function'?fmt(mt):mt.toLocaleString('pt-BR'))+' metros';}
  if(/romaneio/.test(low)){var achRom=[];try{Object.keys(ROMS||{}).forEach(function(k){var d=ROMS[k]||{},id=String(d.nRomaneio||k);if(!num||id===num||id.indexOf(num)>=0)achRom.push({key:k,doc:d,id:id});});}catch(e){}if(num){if(!achRom.length)return 'Não encontrei o romaneio '+num+'. Confira o número informado.';ultimoRomaneioWmsAi=achRom[0];ultimoAssuntoWmsAi='romaneio';return relatorioRomaneio(achRom[0].doc,achRom[0].key);}if(/hoje|data de hoje/.test(low))return romaneiosHoje();if(/geral|todos|resumo completo|resumo dos/.test(low))return resumoRomaneios();return 'Você quer consultar um romaneio específico, os romaneios de hoje ou o resumo geral? Informe o número ou escreva “romaneios hoje” ou “romaneios em geral”.';}
  if(/nf|nota fiscal/.test(low)&&dataConsulta(t))return nfPorData(t);
  if(/(nf|nota fiscal).*(hoje|data de hoje)|(hoje|data de hoje).*(nf|nota fiscal)|(hoje|data de hoje).*(entrou|entraram|quantas)/.test(low))return nfEntradasHoje();
  if(/(quantas|quanto|resumo|total|teve|foram).*(entrada|entrou|entraram|recebimento).*(hoje)|(entrada|entrou|entraram|recebimento).*(hoje)|(quantas|quanto).*(entrou|entraram)/.test(low))return ultimoMaterialWmsAi?entradasHojeDoMaterial(ultimoMaterialWmsAi):resumoMovimentos('entrada');
  if(/(quantas|resumo|total|teve|foram).*(sa[ií]da).*(hoje)|sa[ií]da.*hoje/.test(low))return resumoMovimentos('saida');
  if(/(movimenta[cç][aã]o|movimento|aconteceu|opera[cç][aã]o).*(hoje)|hoje.*(movimenta[cç][aã]o|aconteceu)/.test(low))return resumoMovimentos('');
  if(/vaga|posi[cç][aã]o livre|endere[cç]o livre|ocupa[cç][aã]o/.test(low))return resumoVagas();
  if(/aguardando endere[cç]o|recebimento pendente|pend[eê]ncia.*recebimento/.test(low))return resumoRecebimento();
  if(/quantas.*etiqueta|resumo.*etiqueta|etiquetas.*sistema/.test(low))return resumoEtiquetas();
  if(/quantos.*usu[aá]rio|usu[aá]rios.*(ativo|cadastrado)|lista.*usu[aá]rio/.test(low))return resumoUsuarios();
  if(/etiqueta/.test(low)){var retEt=buscaEtiqueta(t);if(retEt)return retEt;}
  if(/nf|nota fiscal/.test(low)){var achNF=[];try{Object.keys(NFS||{}).forEach(function(k){var n=NFS[k]||{},id=String(n.nNF||n.numero||k);if(!num||id===num||id.indexOf(num)>=0)achNF.push({key:k,doc:n,id:id});});}catch(e){}if(!achNF.length)return num?'Não encontrei a NF '+num+'. Confira o número informado.':'Informe o número da nota fiscal. Exemplo: “consultar NF 40972”.';if(num){ultimaNfWmsAi=achNF[0];ultimoAssuntoWmsAi='nf';return relatorioNF(achNF[0].doc,achNF[0].key);}return 'Encontrei '+achNF.length+' notas. Informe o número da NF para ver fornecedor, produtos, quantidades, chegada e responsável pelo recebimento.';}
  var contextual=respostaContextual(t);if(contextual)return contextual;
  if(num||/onde|localizar|produto|material|endere[cç]o/.test(low)){
   if(!num)return 'Informe o código do material que deseja localizar.';
   var ach=occ.filter(function(x){return String(x.pr||'')===num;});
   if(!ach.length)ach=occ.filter(function(x){return String(x.pr||'').indexOf(num)>=0||String(x.code||x.et||'').indexOf(num)>=0;});
   if(!ach.length)return 'Não temos o material '+num+' nas vagas ocupadas neste momento.';
   var un=typeof unitOf==='function'?unitOf(num):'KG',total=0,locais={},ruas={};
   ach.forEach(function(x){var q=Number(x.q)||0;if(q>0&&q<1e11)total+=q;var local=typeof code==='function'?code(x):(x.addr||x.end||x.pos||x.id||'endereço não informado');locais[local]=1;var rua=String(x.s||local.split('-')[0]||'?').toUpperCase();ruas[rua]=(ruas[rua]||0)+1;});
   var vagas=Object.keys(locais).length,desc=typeof descOf==='function'?(descOf(num)||''):'',media=vagas?total/vagas:0,lista=ach.slice(0,8).map(function(x){var local=typeof code==='function'?code(x):(x.addr||x.end||x.pos||x.id||'endereço não informado');return '• '+local+' · '+(typeof fmt==='function'?fmt(Number(x.q)||0):(Number(x.q)||0))+' '+un;});ultimoMaterialWmsAi={codigo:num,descricao:desc,pontos:99};ultimoAssuntoWmsAi='material';
   var linhas=['Sim, temos o material '+num+' em estoque.'+(desc?'\nDescrição: '+desc:''),'Quantidade total: '+(typeof fmt==='function'?fmt(total):total.toLocaleString('pt-BR'))+' '+un,'Vagas ocupadas: '+vagas,'Média por vaga: '+(typeof fmt==='function'?fmt(media):media.toLocaleString('pt-BR'))+' '+un,'Distribuição: '+Object.keys(ruas).sort().map(function(r){return 'Rua '+r+' ('+ruas[r]+' vaga'+(ruas[r]===1?'':'s')+')';}).join(' · '),'Primeiras vagas:',lista.join('\n')];
   if(vagas>8)linhas.push('... e mais '+(vagas-8)+' vagas. Use “localizar produto '+num+'” para consultar os endereços.');
   return linhas.join('\n');
  }
  return 'Não encontrei uma interpretação segura para essa pergunta e não vou inventar uma resposta. Diga o assunto principal — produto, NF, etiqueta, vaga, entrada, saída, recebimento ou usuário — e eu consulto os dados do WMS.';
 }
 function envia(q){q=String(q||'').trim();if(!q)return;fala(q,'user');inp.value='';setTimeout(function(){fala(resposta(q),'bot');},180);}
 var alertaInicialMostrado=false;
